import cn from 'classnames';
import { TableProps } from './table.types';

export function Table({
  id,
  ':orderCol': orderCol,
  ':itemsRow': itemsRow,
  ':itemsCol': itemsCol,
  className,
  useRootClassName = true,
}: TableProps) {
  return (
    <div id={id} className={cn(useRootClassName ? 'text' : '', className)}>
      <div className="cmp-text">
        <table>
          <tbody>
            {itemsCol && (
              <tr>
                {orderCol.map((col) => (
                  <th key={itemsCol[col].id}>{itemsCol[col].title}</th>
                ))}
              </tr>
            )}
            {itemsRow.map((row, rowIndex) => (
              <tr key={rowIndex}>
                {orderCol.map((col, colIndex) => (
                  <td key={`${col}-${colIndex}`} dangerouslySetInnerHTML={{ __html: row[col] }} />
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default Table;
